<?php
declare(strict_types=1);
require_once __DIR__ . '/app.php';
require_login();
$db = db(); $errors = []; $notice = flash();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    check_csrf(); $action = $_POST['action'] ?? '';
    if ($action === 'create') {
        $email = strtolower(trim($_POST['email'] ?? '')); $password = (string)($_POST['password'] ?? '');
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) $errors[] = 'Enter a valid email address.';
        if (strlen($password) < 10) $errors[] = 'Password must be at least 10 characters.';
        if (!$errors) { try { $stmt=$db->prepare('INSERT INTO users(email,password_hash) VALUES(?,?)'); $stmt->execute([$email,password_hash($password,PASSWORD_DEFAULT)]); flash('User account created.'); redirect('users.php'); } catch(PDOException $e) { $errors[] = $e->getCode()==='23000' ? 'That email address already has an account.' : 'Could not create the account.'; } }
    }
    if ($action === 'reset') {
        $userId = (int)($_POST['user_id'] ?? 0); $password = (string)($_POST['password'] ?? '');
        if (strlen($password) < 10) $errors[] = 'New password must be at least 10 characters.';
        if (!$errors) { $stmt=$db->prepare('UPDATE users SET password_hash=? WHERE id=?'); $stmt->execute([password_hash($password,PASSWORD_DEFAULT),$userId]); flash('Password reset. The user can sign in with the new password.'); redirect('users.php'); }
    }
}
$users = $db->query('SELECT id,email,created_at FROM users ORDER BY email')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#26715d"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="default"><title>User access · Staybook</title><link rel="manifest" href="manifest.webmanifest"><link rel="apple-touch-icon" href="icons/icon-192.png"><link rel="stylesheet" href="style.css?v=6"><script defer src="pwa.js?v=4"></script></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>staybook<small>HOTEL DIRECTORY</small></span></a><div class="topbar-right"><a class="text-link" href="index.php">← Hotels</a><a class="button button-light" href="logout.php">Log out</a></div></header><main class="detail-shell"><div class="breadcrumb"><a href="index.php">Hotels</a><span>/</span><b>User access</b></div><div class="detail-heading"><div><div class="eyebrow">WORKSPACE ACCESS</div><h1>User accounts</h1><p>Create team logins and reset passwords.</p></div></div><?php if($notice): ?><div class="notice success"><?=h($notice['message'])?></div><?php endif; ?><?php if($errors): ?><div class="notice error"><ul><?php foreach($errors as $error): ?><li><?=h($error)?></li><?php endforeach; ?></ul></div><?php endif; ?><section class="panel user-panel"><div class="panel-heading"><div><h2>Create a user</h2><p>Each user signs in with their email and password.</p></div></div><form method="post" class="user-create"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Email address<input type="email" name="email" autocomplete="off" required value="<?=h($_POST['action']==='create'?($_POST['email']??''):'')?>"></label><label>Temporary password<input type="password" name="password" minlength="10" required autocomplete="new-password"><small>At least 10 characters. Share it with the user securely.</small></label><button class="button button-dark" type="submit">Create user <span>→</span></button></form></section><section class="panel users-list"><div class="panel-heading"><div><h2>Current users <span class="count"><?=count($users)?></span></h2><p>Reset a password if a user loses access.</p></div></div><?php foreach($users as $user): ?><div class="user-row"><div class="user-avatar"><?=h(strtoupper(substr($user['email'],0,1)))?></div><div class="user-info"><b><?=h($user['email'])?></b><small>Added <?=h(date('M j, Y',strtotime($user['created_at'])))?></small></div><form method="post" class="reset-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="reset"><input type="hidden" name="user_id" value="<?=$user['id']?>"><input type="password" name="password" placeholder="New password" minlength="10" required autocomplete="new-password"><button class="button button-light" type="submit">Reset password</button></form></div><?php endforeach; ?></section><footer>Staybook <span>·</span> Internal hotel information</footer></main><?php mobile_app_nav('users'); ?></body></html>
